try {
    let followUpCount = 0;
    const seenRecipients = new Set();
    const MAX_DAILY_FOLLOWUPS = 10;
    const MAX_FOLLOWUPS_PER_THREAD = 3; // Max follow-ups if prospect never replies

    // Iterate over ALL input items (threads)
    const results = $input.all().map(item => {
        try {
            const thread = item.json;

            if (!thread) {
                return {
                    json: {
                        needsFollowUp: false,
                        reason: 'Thread data is null or undefined'
                    }
                };
            }

            const messages = thread.messages || [];

            if (!Array.isArray(messages) || messages.length === 0) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Thread has no messages'
                    }
                };
            }

            // Check every message in the thread:
            // All messages must be from us (SENT). If ANY message is not from us, recipient replied!
            let hasIncomingReply = false;
            for (const msg of messages) {
                let isSentByUs = false;
                if (msg.labelIds && Array.isArray(msg.labelIds)) {
                    isSentByUs = msg.labelIds.includes('SENT');
                } else if (msg.labels && Array.isArray(msg.labels)) {
                    isSentByUs = msg.labels.some(l => l.name === 'SENT' || l.id === 'SENT');
                }

                if (!isSentByUs) {
                    hasIncomingReply = true;
                    break;
                }
            }

            // Once they reply once, immediately stop follow-ups
            if (hasIncomingReply) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Recipient replied to this thread. Follow-up stopped.'
                    }
                };
            }

            // Thread only contains emails sent by us (initial outreach + any previous follow-ups).
            // Check if maximum follow-up attempts reached
            if (messages.length > MAX_FOLLOWUPS_PER_THREAD) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Max follow-up attempts reached for this thread (' + (messages.length - 1) + ' follow-ups sent).'
                    }
                };
            }

            const firstMessage = messages[0];
            const lastMessage = messages[messages.length - 1];

            let recipient = lastMessage.To || firstMessage.To;
            let subject = firstMessage.Subject || lastMessage.Subject || '(No Subject)';

            if (!recipient) {
                for (const msg of [lastMessage, firstMessage]) {
                    const payload = msg.payload || {};
                    const headers = payload.headers || [];
                    if (Array.isArray(headers)) {
                        const toHeader = headers.find(h => (h.name || '').toLowerCase() === 'to');
                        const subjectHeader = headers.find(h => (h.name || '').toLowerCase() === 'subject');
                        if (toHeader && !recipient) recipient = toHeader.value;
                        if (subjectHeader && subject === '(No Subject)') subject = subjectHeader.value;
                    }
                }
            }

            if (!recipient) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Could not extract recipient email address'
                    }
                };
            }

            // Daily limit check
            if (followUpCount >= MAX_DAILY_FOLLOWUPS) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Daily limit of ' + MAX_DAILY_FOLLOWUPS + ' follow-ups reached. Skipping.'
                    }
                };
            }

            // Extract recipient first name (check initial message first, then latest)
            let recipientFirstName = '';
            const snippet = firstMessage.snippet || lastMessage.snippet || '';
            const snippetMatch = snippet.match(/^(?:Aloha|Hi|Hello|Dear)\s+([A-Za-z]+)/i);
            if (snippetMatch && snippetMatch[1]) {
                recipientFirstName = snippetMatch[1];
            }

            let recipientEmail = recipient;
            if (recipient) {
                const emailMatch = recipient.match(/<([^>]+)>/);
                if (emailMatch && emailMatch[1]) {
                     recipientEmail = emailMatch[1];
                }
                if (!recipientFirstName) {
                    const nameMatch = recipient.match(/^"?([^"<]+)"?\s*</);
                    if (nameMatch && nameMatch[1]) {
                        recipientFirstName = nameMatch[1].trim().split(' ')[0];
                    }
                }
            }

            // Deduplication guard across threads
            const cleanEmail = (recipientEmail || '').trim().toLowerCase();
            if (cleanEmail && seenRecipients.has(cleanEmail)) {
                return {
                    json: {
                        needsFollowUp: false,
                        threadId: thread.id,
                        reason: 'Duplicate recipient (' + cleanEmail + ') already scheduled for follow-up in this run.'
                    }
                };
            }
            if (cleanEmail) seenRecipients.add(cleanEmail);

            followUpCount++;

            return {
                json: {
                    needsFollowUp: true,
                    threadId: thread.id,
                    lastMessageId: lastMessage.id,
                    messageCount: messages.length,
                    followUpNumber: messages.length,
                    recipient: recipient,
                    recipientEmail: recipientEmail,
                    recipientFirstName: recipientFirstName,
                    originalSubject: subject,
                    lastMessageSnippet: lastMessage.snippet,
                    reason: 'Thread has ' + messages.length + ' sent message(s) from us and 0 replies.'
                }
            };
        } catch (itemError) {
            console.error('Error processing item:', itemError);
            return {
                json: {
                    needsFollowUp: false,
                    threadId: item?.json?.id || 'unknown',
                    reason: 'Error processing thread: ' + itemError.message,
                    errorStack: itemError.stack
                }
            };
        }
    });

    return results;

} catch (error) {
    console.error('Fatal error in follow-up logic:', error);
    return [{
        json: {
            needsFollowUp: false,
            reason: 'Fatal error in workflow: ' + error.message,
            errorStack: error.stack
        }
    }];
}

// Extract and normalize recipient email address
function extractEmail(toStr) {
    if (!toStr) return '';
    const match = toStr.match(/<([^>]+)>/);
    const email = match ? match[1] : toStr;
    return email.trim().toLowerCase();
}

const seenEmails = new Set();
const seenThreads = new Set();
const uniqueItems = [];

for (const item of $input.all()) {
    const json = item.json;

    // Extract To field
    let rawTo = json.To || json.to || '';
    if (!rawTo && json.payload && Array.isArray(json.payload.headers)) {
        const toHeader = json.payload.headers.find(h => (h.name || '').toLowerCase() === 'to');
        if (toHeader) rawTo = toHeader.value;
    }

    const email = extractEmail(rawTo);
    const threadId = json.threadId;

    // Check if either the recipient email or threadId was already processed in this batch
    let isDuplicate = false;
    if (email && seenEmails.has(email)) {
        isDuplicate = true;
    }
    if (threadId && seenThreads.has(threadId)) {
        isDuplicate = true;
    }

    if (!isDuplicate) {
        if (email) seenEmails.add(email);
        if (threadId) seenThreads.add(threadId);
        uniqueItems.push(item);
    }
}

return uniqueItems;

const items = $input.all();
return items.map((item, index) => {
  const json = item.json;
  const firstName = json.recipientFirstName || '';
  const greeting = firstName ? 'Aloha ' + firstName + ',' : 'Aloha,';
  const body = greeting + '\nI just wanted to follow up on my email and see if you had a chance to take a look.\nWe’d love the opportunity to learn a little more about your business and see if there’s anything Zumify could help make easier, whether that’s with your website, technology, systems, or something you’ve been wanting to build.\nNo pressure at all, we’d simply love to connect with another local business and see where we might be able to help.\nIf you’re interested, just reply here and I’d be happy to chat.\nMahalo,';
  const subject = json.originalSubject 
    ? (json.originalSubject.toLowerCase().startsWith('re:') ? json.originalSubject : 'Re: ' + json.originalSubject)
    : 'Re: Following up';

  return {
    json: {
      ...json,
      candidateIndex: index,
      recipientName: firstName || json.recipientEmail,
      subject: subject,
      body: body
    }
  };
});

const incoming = $input.item.json.body || $input.item.json;
let currentCandidate = {};
try {
  currentCandidate = $('Loop Over Follow-ups').item.json || {};
} catch(e) {}

if (!currentCandidate.threadId && incoming.recipientEmail) {
  try {
    const allFormatted = $('Format Follow-up Email').all();
    const found = allFormatted.find(f => (f.json?.recipientEmail || '').toLowerCase() === (incoming.recipientEmail || '').toLowerCase());
    if (found) currentCandidate = found.json;
  } catch(e) {}
}

const subject = (incoming.Subject !== undefined && incoming.Subject !== null && incoming.Subject !== '')
  ? incoming.Subject
  : (currentCandidate.subject || 'Re: Following up');

const body = (incoming['Email Body'] !== undefined && incoming['Email Body'] !== null && incoming['Email Body'] !== '')
  ? incoming['Email Body']
  : (incoming.body || currentCandidate.body || '');

const recipientEmail = incoming.recipientEmail || currentCandidate.recipientEmail;
const recipientFirstName = incoming.recipientName || currentCandidate.recipientFirstName || '';
const threadId = incoming.threadId || currentCandidate.threadId;
const lastMessageId = incoming.lastMessageId || currentCandidate.lastMessageId;

return [{
  json: {
    recipientEmail,
    recipientFirstName,
    subject,
    body,
    threadId,
    lastMessageId,
    decision: 'Approve',
    isEdited: (subject !== currentCandidate.subject || body !== currentCandidate.body)
  }
}];

return [{
  json: {
    status: 'declined',
    recipientEmail: $('Loop Over Follow-ups').item.json?.recipientEmail
  }
}];

return [{
  json: {
    status: 'completed',
    message: 'All pending follow-ups reviewed and processed.'
  }
}];

